import { test, expect } from '@playwright/test';

test.describe('Focus Indicators Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should display visible focus indicator on button elements', async ({ page }) => {
    const button = page.getByRole('button').first();

    // Focus the button
    await button.focus();

    // Check that the button has a visible focus indicator
    const focusStyle = await button.evaluate((el) => {
      const styles = window.getComputedStyle(el);
      return {
        outline: styles.outline,
        outlineWidth: styles.outlineWidth,
        boxShadow: styles.boxShadow,
        backgroundColor: styles.backgroundColor
      };
    });

    // Verify that at least one focus indicator property is set
    const hasFocusIndicator = 
      focusStyle.outline !== 'none' || 
      focusStyle.boxShadow !== 'none' ||
      focusStyle.outlineWidth !== '0px';

    expect(hasFocusIndicator).toBeTruthy();
  });

  test('should display visible focus indicator on link elements', async ({ page }) => {
    const link = page.getByRole('link').first();

    // Focus the link
    await link.focus();

    // Check that the link has a visible focus indicator
    const focusStyle = await link.evaluate((el) => {
      const styles = window.getComputedStyle(el);
      return {
        outline: styles.outline,
        outlineWidth: styles.outlineWidth,
        boxShadow: styles.boxShadow,
        textDecoration: styles.textDecoration
      };
    });

    // Verify that at least one focus indicator property is set
    const hasFocusIndicator = 
      focusStyle.outline !== 'none' || 
      focusStyle.boxShadow !== 'none' ||
      focusStyle.outlineWidth !== '0px' ||
      focusStyle.textDecoration.includes('underline');

    expect(hasFocusIndicator).toBeTruthy();
  });

  test('should display visible focus indicator on input fields', async ({ page }) => {
    const input = page.getByRole('textbox').first();

    // Focus the input
    await input.focus();

    // Check that the input has a visible focus indicator
    const focusStyle = await input.evaluate((el) => {
      const styles = window.getComputedStyle(el);
      return {
        outline: styles.outline,
        outlineWidth: styles.outlineWidth,
        borderColor: styles.borderColor,
        boxShadow: styles.boxShadow
      };
    });

    // Verify that at least one focus indicator property is set
    const hasFocusIndicator = 
      focusStyle.outline !== 'none' || 
      focusStyle.boxShadow !== 'none' ||
      focusStyle.outlineWidth !== '0px' ||
      focusStyle.borderColor !== 'rgb(0, 0, 0)';

    expect(hasFocusIndicator).toBeTruthy();
  });

  test('should maintain focus indicator visibility when tabbing through interactive elements', async ({ page }) => {
    const firstButton = page.getByRole('button').first();

    // Tab to the first button
    await page.keyboard.press('Tab');

    // Get the focused element
    const focusedElement = await page.evaluate(() => {
      return document.activeElement?.tagName;
    });

    // Verify that an element is focused
    expect(focusedElement).not.toBe('BODY');

    // Check that the focused element has visible focus styles
    const focusStyle = await page.evaluate(() => {
      const el = document.activeElement as HTMLElement;
      if (!el) return null;
      const styles = window.getComputedStyle(el);
      return {
        outline: styles.outline,
        outlineWidth: styles.outlineWidth,
        boxShadow: styles.boxShadow
      };
    });

    const hasFocusIndicator = 
      focusStyle?.outline !== 'none' || 
      focusStyle?.boxShadow !== 'none' ||
      focusStyle?.outlineWidth !== '0px';

    expect(hasFocusIndicator).toBeTruthy();
  });

  test('should ensure focus indicator has sufficient contrast', async ({ page }) => {
    const button = page.getByRole('button').first();

    // Focus the button
    await button.focus();

    // Get the computed styles and check contrast
    const contrastInfo = await button.evaluate((el) => {
      const styles = window.getComputedStyle(el);
      const rect = el.getBoundingClientRect();

      return {
        outline: styles.outline,
        outlineColor: styles.outlineColor,
        outlineWidth: styles.outlineWidth,
        boxShadow: styles.boxShadow,
        isVisible: rect.width > 0 && rect.height > 0
      };
    });

    // Verify that focus indicator is visible and has properties set
    expect(contrastInfo.isVisible).toBeTruthy();
    const hasFocusIndicator = 
      contrastInfo.outline !== 'none' || 
      contrastInfo.boxShadow !== 'none' ||
      contrastInfo.outlineWidth !== '0px';

    expect(hasFocusIndicator).toBeTruthy();
  });
});
